namespace Notifications;

/// <summary>Runs a message through validation, throttling, rendering and delivery.</summary>
public sealed class DispatchPipeline
{
    private readonly ITemplateStore _templates;
    private readonly UnsubscribeList _unsubscribed;

    public DispatchPipeline(ITemplateStore templates, UnsubscribeList unsubscribed)
    {
        _templates = templates;
        _unsubscribed = unsubscribed;
    }

    public string Run(Message message, int attempt)
    {
        var error = Validate(message, attempt);
        if (error != null)
            return error;

        var template = _templates.Get(message.Subject);
        if (template == null)
            return "no template";

        var body = Render(message, template);
        return BuildResult(body, attempt);
    }

    private string? Validate(Message message, int attempt)
    {
        if (string.IsNullOrEmpty(message.Body)) return "empty body";
        if (message.Recipient == null) return "invalid recipient";

        var recipient = message.Recipient;
        if (message.Channel == Channel.Email &&
            (string.IsNullOrEmpty(recipient.EmailAddress) || !recipient.EmailAddress.Contains('@')))
            return "invalid email";
        if (message.Channel == Channel.Sms &&
            (string.IsNullOrEmpty(recipient.Phone) || recipient.Phone.Length < 5))
            return "invalid phone";
        if (_unsubscribed.IsUnsubscribed(recipient.EmailAddress)) return "unsubscribed";
        return attempt > 5 ? "throttled" : null;
    }

    private static string Render(Message message, string template) =>
        message.Channel switch
        {
            Channel.Email => template + message.Body,
            Channel.Sms => message.Body,
            Channel.Push => message.Subject,
            _ => message.Body
        };

    private static string BuildResult(string body, int attempt)
    {
        if (attempt > 0 && body.Length > 0) return $"retry:{attempt}:{body.Length}";
        return body.Length == 0 ? "empty render" : $"sent:{body.Length}";
    }
}
